import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();

        int[][] count = new int[4][14];
        boolean[] duplicated = new boolean[4];

        for (int i = 0; i + 3 <= s.length(); i += 3) {
            int rank = Integer.parseInt(s.substring(i, i + 2));
            char suit = s.charAt(i + 2);

            int idx;
            switch (suit) {
                case 'C': idx = 0; break;
                case 'E': idx = 1; break;
                case 'U': idx = 2; break;
                case 'P': idx = 3; break;
                default: idx = -1;
            }

            if (idx != -1) {
                count[idx][rank]++;
                if (count[idx][rank] > 1) {
                    duplicated[idx] = true;
                }
            }
        }

        StringBuilder sb = new StringBuilder();

        for (int idx = 0; idx < 4; idx++) {
            if (duplicated[idx]) {
                sb.append("erro\n");
            } else {
                int missing = 0;
                for (int rank = 1; rank <= 13; rank++) {
                    if (count[idx][rank] == 0) {
                        missing++;
                    }
                }
                sb.append(missing).append('\n');
            }
        }

        System.out.print(sb);
    }
}
